<script lang="ts">let {data,form}=$props();</script><svelte:head><title>标签 · 站长工作台</title></svelte:head><main><h1>标签</h1><p>标签重命名立即影响公开展示；历史版本保留当时名称。</p>{#if form?.error}<p role="alert">{form.error}</p>{/if}{#if form?.success}<p role="status">{form.success}</p>{/if}<form method="post"><label>新标签<input name="name" value={!form?.input?.id?form?.input?.name??'':''} maxlength="100" required/></label><button>添加标签</button></form>{#each data.tags as tag}<form method="post"><input type="hidden" name="id" value={tag.id}/><label>标签名称<input name="name" value={form?.input?.id===tag.id?form.input.name:tag.name} required maxlength="100"/></label><button>保存名称</button></form>{/each}</main><style>form{display:flex;align-items:end;gap:16px;margin-block:24px;flex-wrap:wrap}</style>
